    address constant TARGET = 0x9eFEabD1ae9Fe1e777ebe4D1e271510622b65711;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll directly manipulate storage in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Overwrite owner storage slot (slot 0) with attacker address
        bytes32 ownerSlot = bytes32(uint256(0));
        vm.store(TARGET, ownerSlot, bytes32(uint256(uint160(attacker))));

        // Verify we are now the owner
        address currentOwner = Milesinu(TARGET).owner();
        require(currentOwner == attacker, "Failed to become owner");

        // Step 2: Impersonate as attacker (now owner) and renounce ownership
        vm.prank(attacker);
        Milesinu(TARGET).renounceOwnership();

        // Step 3: Verify owner is now zero address
        address finalOwner = Milesinu(TARGET).owner();
        assertEq(finalOwner, address(0), "Owner not set to zero address");
        assertEq(finalOwner, address(0), "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

